"use client";

import { useState, useEffect } from "react";
import "./styled.component.css";
import Image from "next/image";
import imgrandom from "@/public/coins_banner2.jpg";

import logo from "@/public/images/logo.png";
import menu_line from "@/public/images/menu_line.png";


const TopBrands = () => {
  const [spinsLeft, setSpinsLeft] = useState(3);
  const [totalWin, setTotalWin] = useState(0);

  const maxSpinsPerDay = 3;
  const winAmountPerSpin = 50;
  const baseRealPlayURL = "https://info.topbon.us/easybon";

  const getTodayDate = () => {
    const today = new Date();
    return today.toISOString().split("T")[0];
  };

  const resetDailyData = () => {
    const today = getTodayDate();
    const lastResetDate = localStorage.getItem("lastResetDate");
    if (lastResetDate !== today) {
      localStorage.setItem("lastResetDate", today);
      localStorage.setItem("spinsLeft", maxSpinsPerDay);
      localStorage.setItem("totalWin", 0);
      setSpinsLeft(maxSpinsPerDay);
      setTotalWin(0);
    } else {
      setSpinsLeft(parseInt(localStorage.getItem("spinsLeft"), 10) || 0);
      setTotalWin(parseInt(localStorage.getItem("totalWin"), 10) || 0);
    }
  };

  const buildURLWithParams = (baseURL, params) => {
    const url = new URL(baseURL);
    Object.keys(params).forEach((key) => {
      if (!url.searchParams.has(key) && params[key]) {
        url.searchParams.append(key, params[key]);
      }
    });
    return url.toString();
  };

  useEffect(() => {
    resetDailyData();
  }, []);

  const handleSpin = () => {
    if (spinsLeft > 0) {
      const newSpinsLeft = spinsLeft - 1;
      setSpinsLeft(newSpinsLeft);
      localStorage.setItem("spinsLeft", newSpinsLeft);

      const video = document.getElementById("slotAnimation");
      const sound = document.getElementById("slotSound");

      video.currentTime = 0;
      video.play();

      sound.currentTime = 0;
      sound.play();

      setTimeout(() => {
        sound.pause();
      }, 10000);

      setTimeout(() => {
        const newTotalWin = totalWin + winAmountPerSpin;
        setTotalWin(newTotalWin);
        localStorage.setItem("totalWin", newTotalWin);
      }, 10000);
    } else {
      const urlParams = {
        BV_CLICKID: "some_value", // replace with actual logic to get values
        BV_SRCID: "some_value",
        BV_CAMPID: "some_value",
        BV_GEO: "some_value",
      };
      const realPlayURL = buildURLWithParams(baseRealPlayURL, urlParams);
      window.location.href = realPlayURL;
    }
  };

  return (
    <div className="topbr-tw otp-ver-if">
      <header className="header">
        <img className="header__light" src="assets/images/circle1_1.png" alt="" />
        <div className="container">
          <div className="header__inner">
            <Image className="header__logo" src={logo} alt="logo" />
            {/* <img className="header__logo" src={logo} alt="logo" /> */}
            <nav className="header__nav">
              <a>Do you feel lucky today?</a>
            </nav>
          </div>
          <img className="header__line" src="assets/images/menu_line.png" alt="" />
          <img className="header__dots" src="assets/images/dots_header.png" alt="" />
          <Image className="header__logo" src={menu_line} alt="menu_line" />
          <Image className="header__logo" src={dots_header} alt="dots_header" />

        </div>
      </header>

      <div className="block1">
        <img src="assets/images/design1.png" alt="" className="block1__underimg" />
        <div className="container">
          <div className="block1__inner">
            <div className="block1__left">
              <video
                poster="assets/images/poster.png"
                id="slotAnimation"
                width="100%"
                height="100%"
                preload="auto"
                playsInline
                webkit-playsinline="true"
              >
                <source src="assets/video/slots.mp4" type="video/mp4" />
              </video>
              <audio id="slotSound" src="assets/audio/cas2.mp3"></audio>
              <button className="button" onClick={handleSpin}>
                <div className="button__div">
                  <p className="button__text">
                    {spinsLeft > 0 ? "Spin" : "Go to Real Play"}
                  </p>
                </div>
              </button>
            </div>
            <div className="block1__right">
              <img src="assets/images/dots_1.png" alt="" className="block1__dots" />
              <div className="block1__img">
                <p className="spins-left">Spins left: {spinsLeft}</p>
                <p className="total-win">Total Win: ${totalWin}</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <footer className="footer">
        <div className="container">
          <div className="footer__inner">
            <img src="assets/images/logo.png" alt="" className="footer__logo" />
          </div>
        </div>
      </footer>
    </div>
  );
};

export default TopBrands;
